import{_ as e,o as l,c as t,a2 as i}from"./chunks/framework.DgVVaeR-.js";const _=JSON.parse('{"title":"端末間データ同期（PallaSync）","description":"","frontmatter":{"title":"端末間データ同期（PallaSync）"},"headers":[],"relativePath":"user/sync.md","filePath":"user/sync.md","lastUpdated":1791013521000}'),n={name:"user/sync.md"};function r(o,a,s,c,p,d){return l(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="端末間データ同期-pallasync" tabindex="-1">端末間データ同期（PallaSync） <a class="header-anchor" href="#端末間データ同期-pallasync" aria-label="Permalink to &quot;端末間データ同期（PallaSync）&quot;">​</a></h1><p>PallaSyncは、同じチェーンに参加した端末間でコレクションを同期する機能です。アプリ全体のバックアップや、Pixivアカウントへのログイン共有ではありません。</p><h2 id="同期するデータ" tabindex="-1">同期するデータ <a class="header-anchor" href="#同期するデータ" aria-label="Permalink to &quot;同期するデータ&quot;">​</a></h2><p>実装上の対象は、お気に入りタグ、検索履歴、ミュートしたタグ・ユーザー・作品、既読フィード作品、閲覧履歴です。テーマなどすべての設定、認証トークン、保存済み画像ファイルを一括同期するものではありません。Pixiv上のブックマークやフォローはPixivアカウント側で管理されます。</p><h2 id="端末をつなぐ" tabindex="-1">端末をつなぐ <a class="header-anchor" href="#端末をつなぐ" aria-label="Permalink to &quot;端末をつなぐ&quot;">​</a></h2><ol><li>最初の端末で設定の「PallaSync」を開き、同期サーバーのURLを確認して有効化します。新しいチェーンが作成されます。</li><li>「端末をペアリング」から同期コードの表示画面を開きます。</li><li>追加する端末で同じサーバーを指定し、ペアリング画面の同期コード入力、またはQRコード読み取りを使って既存チェーンに参加します。</li><li>参加端末の一覧と同期ログを確認します。必要に応じて「今すぐ同期」を実行できます。</li></ol><p>各端末で個別に新しいチェーンを作成しても、同じ同期先にはなりません。同期コードはチェーンへ参加するための秘密情報なので、公開しないでください。</p><h2 id="暗号化と解除" tabindex="-1">暗号化と解除 <a class="header-anchor" href="#暗号化と解除" aria-label="Permalink to &quot;暗号化と解除&quot;">​</a></h2><p>送信するレコードの本文は端末側で暗号化します。現在のプロトコルは2.1で、本文にはXChaCha20-Poly1305を使用し、旧2.0形式も読み取ります。チェーンIDなどの配送用情報まで非公開になる仕組みではありません。</p><p>「チェーンから退出」はこの端末を切り離す操作で、「チェーンを削除」は同期先のチェーンを削除する操作です。確認ダイアログの対象を確かめてください。</p><p>技術的な保存場所・暗号処理は<a href="/Palleria/dev/pallasync-engine">PallaSync同期エンジン</a>を参照してください。</p>',11)])])}const P=e(n,[["render",r]]);export{_ as __pageData,P as default};
